INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'cover', 'The Wedding of', 'Ahmad & Siti', '{"eyebrow": "THE WEDDING OF", "groom_name": "Ahmad Nur Syahid", "bride_name": "Siti Sa''diyah", "event_date": "2027-06-20", "guest_greeting_label": "Kepada Yth. Bapak/Ibu/Saudara/i", "button_text": "✧ Buka Undangan ✧", "cover_photo": "https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80", "bismillah_text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ"}', '{}', 1, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'salam', 'Assalamu’alaikum Warahmatullahi Wabarakatuh', 'Ungkapan Rasa Syukur', '{"bismillah": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "greeting": "Assalamu’alaikum Warahmatullahi Wabarakatuh", "quote_verse": "Dan di antara tanda-tanda kebesaran-Nya ialah Dia menciptakan pasangan-pasangan untukmu dari jenismu sendiri, agar kamu cenderung dan merasa tenteram kepadanya, dan Dia menjadikan di antaramu rasa kasih dan sayang.", "quote_source": "QS. Ar-Rum: 21", "lead_text": "Dengan memohon rahmat dan ridha Allah SWT, kami mengundang Bapak/Ibu/Saudara/i untuk menghadiri hari bahagia kami:"}', '{}', 2, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'profile', 'Mempelai Pengantin', 'Sang Mempelai', '{"groom": {"name": "Ahmad Nur Syahid, S.Kom", "nickname": "Ahmad", "parents": "Putra pertama dari Bapak Tasimun & Ibu Musriyati", "instagram": "@ahmad.nursyahid", "photo": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80"}, "bride": {"name": "Siti Sa''diyah, S.Pd", "nickname": "Siti", "parents": "Putri kedua dari Alm. Bapak Dadang Sobandi & Ibu Oom Fathonah", "instagram": "@siti.sadiyah", "photo": "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=400&q=80"}}', '{}', 3, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'countdown', 'Menghitung Hari Bahagia', 'Save The Date', '{"event_date": "2027-06-20T08:00:00", "note": "Kami tak sabar menanti kehadiran Anda di hari istimewa kami"}', '{}', 4, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'akad', 'Akad Nikah', 'Ikrar Sakral', '{"date": "Minggu, 20 Juni 2027", "time": "08.00 - 10.00 WIB", "venue": "Masjid Al-Barokah", "address": "Jl. Emerald Sanctuary No. 8, Bandung, Jawa Barat", "maps_url": "https://maps.google.com/?q=Bandung", "badge": "Akad Nikah"}', '{}', 5, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'reception', 'Resepsi Pernikahan', 'Walimatul ''Ursy', '{"date": "Minggu, 20 Juni 2027", "time": "11.00 WIB - 14.00 WIB (Selesai)", "venue": "Emerald Grand Ballroom", "address": "Jl. Raya Soreang - Banjaran No. 88, Katapang, Bandung", "maps_url": "https://maps.google.com/?q=Katapang+Bandung", "dresscode": "Formal / Batik / Sage & Gold Touch", "badge": "Resepsi"}', '{}', 6, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'location', 'Lokasi Acara', 'Peta & Petunjuk Arah', '{"venue": "Emerald Grand Ballroom", "address": "Jl. Raya Soreang - Banjaran No. 88, Katapang, Bandung, Jawa Barat", "maps_url": "https://maps.google.com/?q=Katapang+Bandung", "waze_url": "https://waze.com/ul?q=Katapang+Bandung", "embed_url": ""}', '{}', 7, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'story', 'Kisah Cinta Kami', 'Our Journey', '{"intro": "Setiap kisah memiliki bab pertama. Inilah babak perjalanan cinta yang mempertemukan kami:", "milestones": [{"year": "2023", "title": "Pertemuan Pertama", "description": "Pertama kali bertegur sapa dalam sebuah proyek sosial literasi anak muda di Bandung."}, {"year": "2025", "title": "Khitbah & Komitmen", "description": "Dengan ridha kedua orang tua dan niat suci beribadah, kami memantapkan langkah menuju jenjang pernikahan."}, {"year": "2027", "title": "Menuju Gerbang Halal", "description": "Menyatukan dua hati, dua keluarga, dalam ikatan sakral pernikahan yang abadi."}]}', '{}', 8, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'gallery', 'Galeri Momen', 'Sweet Memories', '{"layout": "grid", "photos": ["https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80", "https://images.unsplash.com/photo-1511285560929-80b456fea0bc?auto=format&fit=crop&w=600&q=80", "https://images.unsplash.com/photo-1583939003579-730e3918a45a?auto=format&fit=crop&w=600&q=80", "https://images.unsplash.com/photo-1465495976277-4387d4b0b4c6?auto=format&fit=crop&w=600&q=80"]}', '{}', 9, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'video', 'Video Prewedding', 'Teaser Kenangan', '{"video_url": "https://www.youtube.com/embed/dQw4w9WgXcQ", "caption": "Cuplikan teaser video kebersamaan kami."}', '{}', 10, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'rsvp', 'Konfirmasi Kehadiran', 'RSVP', '{"note": "Kehadiran dan doa restu Anda merupakan hadiah terindah bagi kami.", "max_guests": 5}', '{}', 11, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'guestbook', 'Buku Tamu & Doa Restu', 'Wishes & Prayers', '{"note": "Tinggalkan doa dan harapan terbaik untuk kedua mempelai."}', '{}', 12, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'envelope', 'Tanda Kasih & Hadiah', 'Digital Gift & Kado', '{"note": "Doa restu Anda adalah karunia terindah. Namun jika ingin memberikan tanda kasih secara digital, Anda dapat melalui rekening atau dompet digital berikut:", "accounts": [{"bank": "BCA", "number": "8420192831", "holder": "Ahmad Nur Syahid"}, {"bank": "Bank Syariah Indonesia (BSI)", "number": "7192830192", "holder": "Siti Sa''diyah"}, {"bank": "DANA / GoPay", "number": "081234567890", "holder": "Ahmad Nur Syahid"}], "shipping_address": "Emerald Residence Blok C-12, Katapang, Kabupaten Bandung 40921 (Up: Ahmad & Siti)"}', '{}', 13, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'health_protocol', 'Kenyamanan Acara', 'Panduan Kehadiran', '{"items": [{"icon": "✨", "title": "Hadir Tepat Waktu", "desc": "Mohon berkenan hadir sesuai jam acara agar prosesi berjalan khidmat."}, {"icon": "👗", "title": "Dress Code", "desc": "Nuansa warna Sage, Gold, atau busana batik formal sopan."}, {"icon": "🤲", "title": "Doa & Restu", "desc": "Memberikan doa tulus bagi kelanggengan kedua mempelai."}]}', '{}', 14, 1);
INSERT INTO invitation_sections (invitation_id, section_key, title, subtitle, content_json, style_json, order_index, is_visible) VALUES (1, 'closing', 'Terima Kasih', 'Wassalamu’alaikum Warahmatullahi Wabarakatuh', '{"message": "Merupakan suatu kehormatan dan kebahagiaan bagi kami apabila Bapak/Ibu/Saudara/i berkenan hadir untuk memberikan doa restu kepada kami.", "footer_names": "Ahmad Nur Syahid & Siti Sa''diyah", "family_closing": "Beserta Keluarga Besar Kedua Mempelai"}', '{}', 15, 1);

