('Emerald Gold Luxury (Default)', 'Template klasik mewah hijau zamrud dan emas dengan 15 seksi lengkap.', 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=400&q=80', 'emerald_gold', 1, '{"theme_code": "emerald_gold", "animation_settings": {"enabled": true, "reduce_motion_respect": true, "opening": {"type": "envelope", "duration": 1.2, "delay": 0.2, "intensity": "moderate"}, "text": {"type": "fade_up", "duration": 0.8, "delay": 0.15, "intensity": "moderate"}, "photo": {"type": "ken_burns", "duration": 1.0, "intensity": "subtle"}, "ornament": {"type": "gold_dust", "speed": "normal", "intensity": "moderate"}, "transition": {"type": "smooth_fade", "duration": 0.6}}, "background_settings": {"type": "gradient", "color": "#073f35", "gradient": "radial-gradient(ellipse at center, #155e4c 0%, #073f35 65%, #052d27 100%)", "pattern": "arabesque", "pattern_opacity": 0.08, "image_url": "", "image_opacity": 0.15, "particles": "gold_dust", "particles_intensity": "medium", "show_floral_corner": true, "show_islamic_arch": true, "divider_style": "diamond"}, "sound_settings": {"enabled": true, "music_title": "Romantic Piano & Strings (Royalty-Free)", "music_url": "https://assets.mixkit.co/music/preview/mixkit-wedding-waltz-piano-242.mp3", "volume": 0.75, "autoplay_on_open": true, "button_icon": "vinyl", "button_pos": "bottom-right", "button_animation": "spin"}, "design_settings": {"heading_font": "Playfair Display", "body_font": "DM Sans", "font_scale": "medium", "button_shape": "rounded", "button_radius": "8px", "card_radius": "12px", "photo_frame": "arch", "section_spacing": "standard", "gallery_layout": "grid2"}}', '[{"key": "cover", "title": "The Wedding of", "subtitle": "Ahmad & Siti", "content": {"eyebrow": "THE WEDDING OF", "groom_name": "Ahmad Nur Syahid", "bride_name": "Siti Sa''diyah", "event_date": "2027-06-20", "guest_greeting_label": "Kepada Yth. Bapak/Ibu/Saudara/i", "button_text": "✧ Buka Undangan ✧", "cover_photo": "https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80", "bismillah_text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ"}, "order": 1, "visible": 1}, {"key": "salam", "title": "Assalamu’alaikum Warahmatullahi Wabarakatuh", "subtitle": "Ungkapan Rasa Syukur", "content": {"bismillah": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "greeting": "Assalamu’alaikum Warahmatullahi Wabarakatuh", "quote_verse": "Dan di antara tanda-tanda kebesaran-Nya ialah Dia menciptakan pasangan-pasangan untukmu dari jenismu sendiri, agar kamu cenderung dan merasa tenteram kepadanya, dan Dia menjadikan di antaramu rasa kasih dan sayang.", "quote_source": "QS. Ar-Rum: 21", "lead_text": "Dengan memohon rahmat dan ridha Allah SWT, kami mengundang Bapak/Ibu/Saudara/i untuk menghadiri hari bahagia kami:"}, "order": 2, "visible": 1}, {"key": "profile", "title": "Mempelai Pengantin", "subtitle": "Sang Mempelai", "content": {"groom": {"name": "Ahmad Nur Syahid, S.Kom", "nickname": "Ahmad", "parents": "Putra pertama dari Bapak Tasimun & Ibu Musriyati", "instagram": "@ahmad.nursyahid", "photo": "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80"}, "bride": {"name": "Siti Sa''diyah, S.Pd", "nickname": "Siti", "parents": "Putri kedua dari Alm. Bapak Dadang Sobandi & Ibu Oom Fathonah", "instagram": "@siti.sadiyah", "photo": "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=400&q=80"}}, "order": 3, "visible": 1}, {"key": "countdown", "title": "Menghitung Hari Bahagia", "subtitle": "Save The Date", "content": {"event_date": "2027-06-20T08:00:00", "note": "Kami tak sabar menanti kehadiran Anda di hari istimewa kami"}, "order": 4, "visible": 1}, {"key": "akad", "title": "Akad Nikah", "subtitle": "Ikrar Sakral", "content": {"date": "Minggu, 20 Juni 2027", "time": "08.00 - 10.00 WIB", "venue": "Masjid Al-Barokah", "address": "Jl. Emerald Sanctuary No. 8, Bandung, Jawa Barat", "maps_url": "https://maps.google.com/?q=Bandung", "badge": "Akad Nikah"}, "order": 5, "visible": 1}, {"key": "reception", "title": "Resepsi Pernikahan", "subtitle": "Walimatul ''Ursy", "content": {"date": "Minggu, 20 Juni 2027", "time": "11.00 WIB - 14.00 WIB (Selesai)", "venue": "Emerald Grand Ballroom", "address": "Jl. Raya Soreang - Banjaran No. 88, Katapang, Bandung", "maps_url": "https://maps.google.com/?q=Katapang+Bandung", "dresscode": "Formal / Batik / Sage & Gold Touch", "badge": "Resepsi"}, "order": 6, "visible": 1}, {"key": "location", "title": "Lokasi Acara", "subtitle": "Peta & Petunjuk Arah", "content": {"venue": "Emerald Grand Ballroom", "address": "Jl. Raya Soreang - Banjaran No. 88, Katapang, Bandung, Jawa Barat", "maps_url": "https://maps.google.com/?q=Katapang+Bandung", "waze_url": "https://waze.com/ul?q=Katapang+Bandung", "embed_url": ""}, "order": 7, "visible": 1}, {"key": "story", "title": "Kisah Cinta Kami", "subtitle": "Our Journey", "content": {"intro": "Setiap kisah memiliki bab pertama. Inilah babak perjalanan cinta yang mempertemukan kami:", "milestones": [{"year": "2023", "title": "Pertemuan Pertama", "description": "Pertama kali bertegur sapa dalam sebuah proyek sosial literasi anak muda di Bandung."}, {"year": "2025", "title": "Khitbah & Komitmen", "description": "Dengan ridha kedua orang tua dan niat suci beribadah, kami memantapkan langkah menuju jenjang pernikahan."}, {"year": "2027", "title": "Menuju Gerbang Halal", "description": "Menyatukan dua hati, dua keluarga, dalam ikatan sakral pernikahan yang abadi."}]}, "order": 8, "visible": 1}, {"key": "gallery", "title": "Galeri Momen", "subtitle": "Sweet Memories", "content": {"layout": "grid", "photos": ["https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80", "https://images.unsplash.com/photo-1511285560929-80b456fea0bc?auto=format&fit=crop&w=600&q=80", "https://images.unsplash.com/photo-1583939003579-730e3918a45a?auto=format&fit=crop&w=600&q=80", "https://images.unsplash.com/photo-1465495976277-4387d4b0b4c6?auto=format&fit=crop&w=600&q=80"]}, "order": 9, "visible": 1}, {"key": "video", "title": "Video Prewedding", "subtitle": "Teaser Kenangan", "content": {"video_url": "https://www.youtube.com/embed/dQw4w9WgXcQ", "caption": "Cuplikan teaser video kebersamaan kami."}, "order": 10, "visible": 1}, {"key": "rsvp", "title": "Konfirmasi Kehadiran", "subtitle": "RSVP", "content": {"note": "Kehadiran dan doa restu Anda merupakan hadiah terindah bagi kami.", "max_guests": 5}, "order": 11, "visible": 1}, {"key": "guestbook", "title": "Buku Tamu & Doa Restu", "subtitle": "Wishes & Prayers", "content": {"note": "Tinggalkan doa dan harapan terbaik untuk kedua mempelai."}, "order": 12, "visible": 1}, {"key": "envelope", "title": "Tanda Kasih & Hadiah", "subtitle": "Digital Gift & Kado", "content": {"note": "Doa restu Anda adalah karunia terindah. Namun jika ingin memberikan tanda kasih secara digital, Anda dapat melalui rekening atau dompet digital berikut:", "accounts": [{"bank": "BCA", "number": "8420192831", "holder": "Ahmad Nur Syahid"}, {"bank": "Bank Syariah Indonesia (BSI)", "number": "7192830192", "holder": "Siti Sa''diyah"}, {"bank": "DANA / GoPay", "number": "081234567890", "holder": "Ahmad Nur Syahid"}], "shipping_address": "Emerald Residence Blok C-12, Katapang, Kabupaten Bandung 40921 (Up: Ahmad & Siti)"}, "order": 13, "visible": 1}, {"key": "health_protocol", "title": "Kenyamanan Acara", "subtitle": "Panduan Kehadiran", "content": {"items": [{"icon": "✨", "title": "Hadir Tepat Waktu", "desc": "Mohon berkenan hadir sesuai jam acara agar prosesi berjalan khidmat."}, {"icon": "👗", "title": "Dress Code", "desc": "Nuansa warna Sage, Gold, atau busana batik formal sopan."}, {"icon": "🤲", "title": "Doa & Restu", "desc": "Memberikan doa tulus bagi kelanggengan kedua mempelai."}]}, "order": 14, "visible": 1}, {"key": "closing", "title": "Terima Kasih", "subtitle": "Wassalamu’alaikum Warahmatullahi Wabarakatuh", "content": {"message": "Merupakan suatu kehormatan dan kebahagiaan bagi kami apabila Bapak/Ibu/Saudara/i berkenan hadir untuk memberikan doa restu kepada kami.", "footer_names": "Ahmad Nur Syahid & Siti Sa''diyah", "family_closing": "Beserta Keluarga Besar Kedua Mempelai"}, "order": 15, "visible": 1}]');

