INSERT OR IGNORE INTO event_categories (code, name, icon, description, fields_json, default_sections_json, is_active, is_builtin, order_index) VALUES ('acara_islami', 'Peringatan Hari Besar Islam', '🌙', 'Maulid Nabi, Isra Mi''raj, Nuzulul Qur''an, Tabligh Akbar.', '[{"key": "celebration_name", "label": "Nama Hari Besar", "type": "text", "required": true, "placeholder": "Peringatan Maulid Nabi Muhammad SAW 1448 H"}, {"key": "theme_text", "label": "Tema Acara", "type": "text", "required": false, "placeholder": "Meneladani Akhlak Mulia Rasulullah SAW"}, {"key": "speaker_name", "label": "Penceramah Tamu", "type": "text", "required": false, "placeholder": "Habib Jindan bin Novel bin Jindan"}, {"key": "committee_name", "label": "Panitia Penyelenggara", "type": "text", "required": false, "placeholder": "Majelis Ta''lim Darul Musthofa"}, {"key": "event_date", "label": "Hari & Tanggal", "type": "date", "required": true}, {"key": "event_time", "label": "Waktu Acara", "type": "text", "required": false}, {"key": "venue", "label": "Lokasi", "type": "text", "required": false}, {"key": "address", "label": "Alamat", "type": "textarea", "required": false}]', '["cover", "salam", "profile_speaker", "countdown", "event_detail", "location", "rundown", "rsvp", "guestbook", "closing"]', 1, 1, 11);
INSERT OR IGNORE INTO event_categories (code, name, icon, description, fields_json, default_sections_json, is_active, is_builtin, order_index) VALUES ('umum', 'Undangan Umum / Kustom', '📜', 'Acara bebas apa pun: pameran, gathering, konser, seminar, dll.', '[{"key": "event_title", "label": "Judul Acara", "type": "text", "required": true, "placeholder": "Annual Gathering & Awarding Night"}, {"key": "host_name", "label": "Penyelenggara / Host", "type": "text", "required": true, "placeholder": "Komunitas Kreatif Digital"}, {"key": "event_desc", "label": "Deskripsi Acara", "type": "textarea", "required": false}, {"key": "event_date", "label": "Tanggal Acara", "type": "date", "required": true}, {"key": "event_time", "label": "Waktu Acara", "type": "text", "required": false}, {"key": "venue", "label": "Tempat", "type": "text", "required": false}, {"key": "address", "label": "Alamat", "type": "textarea", "required": false}]', '["cover", "description", "countdown", "event_detail", "location", "rundown", "gallery", "rsvp", "guestbook", "closing"]', 1, 1, 12);

